        { f: 'ε_{back} = −N ΔΦ_B / Δt', name: 'القوة الدافعة المضادة', read: 'تحسب من قانون فراداي', vars: [], when: 'لحساب ε_{back} من تغير الفيض.', note: 'تزداد بزيادة سرعة الدوران وعدد اللفات ومساحة اللفة وكثافة الفيض.' }
